    for pid, pname in docred_rel_types.items():
        pname_tokens = set(pname.lower().split())
        if rel_tokens and pname_tokens:
            overlap = len(rel_tokens & pname_tokens)
            union = len(rel_tokens | pname_tokens)
            ratio = overlap / union
            if ratio > 0.8 and ratio > best_overlap:
                best_overlap = ratio
                best_pid = pid
    if best_pid:
        return best_pid
    for pid, pname in docred_rel_types.items():
        if levenshtein(key, pname.lower()) <= 2:
            return pid
    return None

docred_kappa = {}
docred_valid_pairs_set = {}
for pid, info in docred_rel_constraints.items():
    vp = info['valid_pairs']
    docred_kappa[pid] = 1 - len(vp) / total_pairs_docred
    docred_valid_pairs_set[pid] = set(tuple(p) for p in vp)

docred_counts = defaultdict(lambda: {'total': 0, 'violations': 0})
